<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {galleryImages} from '../../data/gallery.js';
import {newJigsaw,validateJigsaw,swapJigsaw,rotateJigsaw,hintJigsaw,jigsawSolved} from '../../room/jigsaw.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {recordActivity} from '../../room/activityLog.js';
const pictures=galleryImages.filter(i=>i.id==='quiet-guitar'||i.id==='pink-frequency'||i.id==='live-ticket'||Math.max(i.width||0,i.height||0)>=700).slice(0,12);
const validate=v=>{if(!v||v.version!==1)throw new Error();return {version:1,image:pictures.some(p=>p.id===v.image)?v.image:pictures[0].id,puzzle:validateJigsaw(v.puzzle),best:typeof v.best==='object'&&v.best?Object.fromEntries(Object.entries(v.best).filter(([k,n])=>/^\w[\w-]{0,80}$/.test(k)&&Number.isInteger(n)&&n>0).slice(0,40)): {}};};
const {state,saved}=useLocalDraft('hitori-room:jigsaw:v1',{version:1,image:pictures[0].id,puzzle:newJigsaw(),best:{}},validate),selected=ref(-1),preview=ref(false),square=ref(''),loading=ref(false),message=ref('选中一块，再点另一块交换；桌面也可以拖动交换。'),dragged=ref(-1);
let revision=0,alive=true;
const puzzle=computed(()=>state.value.puzzle),picture=computed(()=>pictures.find(p=>p.id===state.value.image)),solved=computed(()=>jigsawSolved(puzzle.value));
const best=computed(()=>state.value.best[`${state.value.image}-${puzzle.value.size}-${Number(puzzle.value.rotating)}`]);
const asset=path=>`${import.meta.env.BASE_URL}${path}`;
watch(()=>state.value.image,async()=>{const token=++revision;loading.value=true;try{const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=asset(picture.value.src);});if(!alive||token!==revision)return;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=900;const c=canvas.getContext('2d'),size=Math.min(image.naturalWidth,image.naturalHeight);c.drawImage(image,(image.naturalWidth-size)/2,(image.naturalHeight-size)/2,size,size,0,0,900,900);square.value=canvas.toDataURL('image/jpeg',.9);}catch{if(alive)message.value='这张图片暂时无法读取，换一张试试。';}finally{if(alive&&token===revision)loading.value=false;}},{immediate:true});
function finish(was){if(!was&&solved.value){const key=`${state.value.image}-${puzzle.value.size}-${Number(puzzle.value.rotating)}`;state.value.best[key]=Math.min(state.value.best[key]||Infinity,puzzle.value.moves||1);message.value='画面完整了。每一小块，都被你认真放回来了。';recordActivity('jigsaw',`${picture.value.title} · ${puzzle.value.moves} 次操作`,`${puzzle.value.seed}`);}}
function pick(index){if(loading.value||solved.value)return;if(selected.value<0){selected.value=index;return;}const before=solved.value;state.value.puzzle=swapJigsaw(puzzle.value,selected.value,index);selected.value=-1;finish(before);}
function rotate(){if(selected.value<0)return;const before=solved.value;state.value.puzzle=rotateJigsaw(puzzle.value,selected.value);finish(before);}
function hint(){const before=solved.value;state.value.puzzle=hintJigsaw(puzzle.value);selected.value=-1;message.value='帮你归位了一块，继续看看其他地方。';finish(before);}
function restart(){state.value.puzzle=newJigsaw(puzzle.value.size,Date.now(),puzzle.value.rotating);selected.value=-1;message.value='新的排列，准备好了。';}
function drop(index){if(dragged.value<0||solved.value||loading.value)return;const before=solved.value;state.value.puzzle=swapJigsaw(puzzle.value,dragged.value,index);dragged.value=-1;selected.value=-1;finish(before);}
onBeforeUnmount(()=>{alive=false;revision++;});
</script>
<template><section class="room-panel" aria-labelledby="jigsaw-title"><div class="pg-heading"><div><p class="pg-kicker">PIECE BY PIECE / 把心动拼回来</p><h2 id="jigsaw-title">每一小块，都有它的位置。</h2><p class="room-intro">从收藏中选图，点击交换或拖动交换；旋转挑战里还要调整每块的方向。</p></div><span class="pg-number">14</span></div><div class="room-fields"><label class="room-field">选择图片<select v-model="state.image" @change="restart"><option v-for="item in pictures" :key="item.id" :value="item.id">{{item.title}}</option></select></label><label class="room-field">拼图块数<select v-model.number="state.puzzle.size" @change="restart"><option :value="3">3 × 3 · 轻松</option><option :value="4">4 × 4 · 标准</option><option :value="5">5 × 5 · 挑战</option></select></label></div><label class="room-check"><input v-model="state.puzzle.rotating" type="checkbox" @change="restart">加入旋转挑战</label>
  <div class="jigsaw-wrap"><div v-if="loading" class="pg-alert" role="status">正在准备图片…</div><div v-else class="jigsaw-board" :style="{'--pieces':puzzle.size}" :data-solved="solved" role="group" aria-label="点击两块交换拼图"><button v-for="(id,index) in puzzle.tiles" :key="index" type="button" :data-tile="id" :data-slot="index" :aria-label="`第${index+1}格，画面块${id+1}`" :aria-pressed="selected===index" :class="{'is-correct':id===index&&puzzle.rotations[id]===0}" :draggable="!solved&&!loading" @dragstart="dragged=index" @dragend="dragged=-1" @dragover.prevent @drop.prevent="drop(index)" @click="pick(index)" @keydown.space.prevent="selected=index;rotate()"><span :style="{backgroundImage:`url(${square})`,backgroundSize:`${puzzle.size*100}% ${puzzle.size*100}%`,backgroundPosition:`${id%puzzle.size/(puzzle.size-1)*100}% ${Math.floor(id/puzzle.size)/(puzzle.size-1)*100}%`,transform:`rotate(${puzzle.rotations[id]*90}deg)`}"></span><small>{{index+1}}</small></button></div><img v-if="preview&&square" :src="square" alt="拼图完整参考图" class="jigsaw-reference"></div>
  <div class="pg-toolbar"><button type="button" :aria-pressed="preview" @click="preview=!preview">{{preview?'收起参考图':'看一眼完整画面'}}</button><button type="button" :disabled="!puzzle.rotating||selected<0||solved" @click="rotate">旋转选中块 ↻</button><button id="jigsaw-hint" type="button" :disabled="solved||loading" @click="hint">帮我归位一块</button><button type="button" @click="restart">重新打乱</button></div><p class="pg-small">本机最佳 {{best?`${best} 次操作`:'还没完成'}} · 已操作 {{puzzle.moves}} 次 · 使用 {{puzzle.hints}} 次提示 · 已归位 {{puzzle.tiles.filter((id,i)=>id===i&&puzzle.rotations[id]===0).length}} / {{puzzle.tiles.length}} 块</p><div v-if="solved" class="pg-result"><span class="pg-score">✦</span><h3>这一张，完整了。</h3><p>{{picture.title}} · {{puzzle.moves}} 次操作 · {{puzzle.hints}} 次提示</p></div><p class="pg-status" role="status">{{message}}</p><p class="pg-small">{{saved?'图片选择、排列与最佳记录会保存在本机。':'浏览器无法保存，本次仍可拼图。'}} 图片沿用收藏区素材，拼图采用中央方形取景，不修改原文件。</p></section></template>
<style scoped>.jigsaw-wrap{position:relative;max-width:680px;margin:24px auto}.jigsaw-board{display:grid;grid-template-columns:repeat(var(--pieces),minmax(0,1fr));gap:4px;background:#70586f;border:5px solid #70586f}.jigsaw-board button{aspect-ratio:1;padding:0;min-height:0;border:0;position:relative;overflow:hidden;background:#e5d5ce;display:block}.jigsaw-board button>span{position:absolute;inset:0;background-repeat:no-repeat;pointer-events:none}.jigsaw-board button>small{position:absolute;left:3px;bottom:3px;background:#49374b99;color:#fff3e1;font:9px monospace;padding:3px 4px;pointer-events:none}.jigsaw-board button[aria-pressed=true]{outline:4px solid #ffe0a0;outline-offset:-5px;z-index:1}.jigsaw-board .is-correct{box-shadow:inset 0 0 0 2px #b9d6be}.jigsaw-reference{position:absolute;right:10px;top:10px;width:42%;height:auto;border:4px solid #fff4df;box-shadow:0 4px 16px #2e233e44;pointer-events:none}@media(max-width:500px){.jigsaw-board{gap:3px;border-width:3px}.jigsaw-board button>small{font-size:8px;padding:2px}}</style>
